BEGIN TRANSACTION;
CREATE TABLE audit_events (
	event_id INTEGER NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_id VARCHAR(50) NOT NULL, 
	event_type VARCHAR(50) NOT NULL, 
	old_value VARCHAR(5000), 
	new_value VARCHAR(5000), 
	event_timestamp DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	performed_by VARCHAR(100) NOT NULL, 
	reason VARCHAR(1000), 
	PRIMARY KEY (event_id), 
	CONSTRAINT ck_audit_event_type CHECK (event_type IN ('CREATED', 'UPDATED', 'STATUS_CHANGED', 'DELETED', 'VERIFIED', 'CLOSED'))
);
CREATE TABLE bom_lines (
	bom_line_id INTEGER NOT NULL, 
	bom_id VARCHAR(30) NOT NULL, 
	material_code VARCHAR(30) NOT NULL, 
	material_description VARCHAR(100) NOT NULL, 
	quantity_required FLOAT NOT NULL, 
	unit_of_measure VARCHAR(20) NOT NULL, 
	scrap_allowance_pct FLOAT NOT NULL, 
	PRIMARY KEY (bom_line_id), 
	CONSTRAINT uq_bom_material UNIQUE (bom_id, material_code), 
	CONSTRAINT ck_bom_quantity CHECK (quantity_required > 0), 
	CONSTRAINT ck_bom_scrap CHECK (scrap_allowance_pct >= 0 AND scrap_allowance_pct <= 100), 
	FOREIGN KEY(bom_id) REFERENCES boms (bom_id)
);
CREATE TABLE boms (
	bom_id VARCHAR(30) NOT NULL, 
	product_id VARCHAR(20) NOT NULL, 
	version INTEGER NOT NULL, 
	effective_from DATE NOT NULL, 
	effective_to DATE, 
	lifecycle_status VARCHAR(20) NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (bom_id), 
	CONSTRAINT uq_product_bom_version UNIQUE (product_id, version), 
	CONSTRAINT ck_bom_version CHECK (version > 0), 
	CONSTRAINT ck_bom_dates CHECK (effective_to IS NULL OR effective_to >= effective_from), 
	CONSTRAINT ck_bom_status CHECK (lifecycle_status IN ('DRAFT', 'ACTIVE', 'OBSOLETE')), 
	FOREIGN KEY(product_id) REFERENCES products (product_id)
);
CREATE TABLE corrective_actions (
	capa_id VARCHAR(30) NOT NULL, 
	defect_id VARCHAR(30) NOT NULL, 
	root_cause VARCHAR(1000), 
	containment_action VARCHAR(1000), 
	corrective_action VARCHAR(1000), 
	preventive_action VARCHAR(1000), 
	assigned_to VARCHAR(100) NOT NULL, 
	opened_at DATETIME NOT NULL, 
	due_date DATE NOT NULL, 
	verified_at DATETIME, 
	closed_at DATETIME, 
	verification_result VARCHAR(20) NOT NULL, 
	lifecycle_status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (capa_id), 
	CONSTRAINT ck_capa_verification CHECK (verification_result IN ('PENDING', 'PASSED', 'FAILED')), 
	CONSTRAINT ck_capa_status CHECK (lifecycle_status IN ('OPEN', 'INVESTIGATION', 'ACTION_IN_PROGRESS', 'VERIFICATION', 'CLOSED', 'CANCELLED')), 
	CONSTRAINT ck_capa_verified_before_closure CHECK (closed_at IS NULL OR verified_at IS NOT NULL), 
	CONSTRAINT ck_capa_successful_verification CHECK (closed_at IS NULL OR verification_result = 'PASSED'), 
	CONSTRAINT ck_capa_verification_date CHECK (verified_at IS NULL OR verified_at >= opened_at), 
	CONSTRAINT ck_capa_closure_date CHECK (closed_at IS NULL OR closed_at >= verified_at), 
	FOREIGN KEY(defect_id) REFERENCES defects (defect_id)
);
CREATE TABLE defects (
	defect_id VARCHAR(30) NOT NULL, 
	inspection_id VARCHAR(40) NOT NULL, 
	order_id VARCHAR(30) NOT NULL, 
	execution_id INTEGER, 
	lot_id VARCHAR(50), 
	defect_category VARCHAR(50) NOT NULL, 
	defect_description VARCHAR(500) NOT NULL, 
	defect_quantity INTEGER NOT NULL, 
	severity VARCHAR(20) NOT NULL, 
	detected_at DATETIME NOT NULL, 
	defect_status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (defect_id), 
	CONSTRAINT ck_defect_quantity CHECK (defect_quantity > 0), 
	CONSTRAINT ck_defect_severity CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')), 
	CONSTRAINT ck_defect_status CHECK (defect_status IN ('OPEN', 'UNDER_REVIEW', 'CONTAINED', 'RESOLVED')), 
	FOREIGN KEY(inspection_id) REFERENCES inspection_results (inspection_id), 
	FOREIGN KEY(order_id) REFERENCES production_orders (order_id), 
	FOREIGN KEY(execution_id) REFERENCES order_machine_executions (execution_id), 
	FOREIGN KEY(lot_id) REFERENCES material_lots (lot_id)
);
CREATE TABLE inspection_plans (
	inspection_plan_id VARCHAR(30) NOT NULL, 
	product_id VARCHAR(20) NOT NULL, 
	inspection_name VARCHAR(100) NOT NULL, 
	characteristic VARCHAR(100) NOT NULL, 
	inspection_stage VARCHAR(30) NOT NULL, 
	lower_limit FLOAT, 
	upper_limit FLOAT, 
	unit_of_measure VARCHAR(20), 
	sample_size INTEGER NOT NULL, 
	lifecycle_status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (inspection_plan_id), 
	CONSTRAINT ck_inspection_sample_size CHECK (sample_size > 0), 
	CONSTRAINT ck_inspection_limits CHECK (lower_limit IS NULL OR upper_limit IS NULL OR upper_limit >= lower_limit), 
	CONSTRAINT ck_inspection_stage CHECK (inspection_stage IN ('INCOMING', 'IN_PROCESS', 'FINAL')), 
	CONSTRAINT ck_inspection_plan_status CHECK (lifecycle_status IN ('ACTIVE', 'INACTIVE')), 
	FOREIGN KEY(product_id) REFERENCES products (product_id)
);
CREATE TABLE inspection_results (
	inspection_id VARCHAR(40) NOT NULL, 
	inspection_plan_id VARCHAR(30) NOT NULL, 
	order_id VARCHAR(30) NOT NULL, 
	execution_id INTEGER, 
	inspection_date DATETIME NOT NULL, 
	inspected_quantity INTEGER NOT NULL, 
	passed_quantity INTEGER NOT NULL, 
	failed_quantity INTEGER NOT NULL, 
	measured_value FLOAT, 
	inspection_status VARCHAR(20) NOT NULL, 
	inspector_name VARCHAR(100) NOT NULL, 
	PRIMARY KEY (inspection_id), 
	CONSTRAINT ck_inspected_quantity CHECK (inspected_quantity > 0), 
	CONSTRAINT ck_inspection_result_quantities CHECK (passed_quantity >= 0 AND failed_quantity >= 0), 
	CONSTRAINT ck_inspection_quantity_reconciliation CHECK (passed_quantity + failed_quantity <= inspected_quantity), 
	CONSTRAINT ck_inspection_result_status CHECK (inspection_status IN ('PASS', 'FAIL', 'CONDITIONAL')), 
	FOREIGN KEY(inspection_plan_id) REFERENCES inspection_plans (inspection_plan_id), 
	FOREIGN KEY(order_id) REFERENCES production_orders (order_id), 
	FOREIGN KEY(execution_id) REFERENCES order_machine_executions (execution_id)
);
CREATE TABLE machines (
	machine_id VARCHAR(20) NOT NULL, 
	machine_name VARCHAR(100) NOT NULL, 
	machine_type VARCHAR(50) NOT NULL, 
	location VARCHAR(100) NOT NULL, 
	installation_date DATE NOT NULL, 
	lifecycle_status VARCHAR(20) NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (machine_id), 
	CONSTRAINT ck_machine_status CHECK (lifecycle_status IN ('ACTIVE', 'MAINTENANCE', 'INACTIVE'))
);
CREATE TABLE material_consumptions (
	consumption_id INTEGER NOT NULL, 
	order_id VARCHAR(30) NOT NULL, 
	lot_id VARCHAR(50) NOT NULL, 
	material_code VARCHAR(30) NOT NULL, 
	consumed_quantity FLOAT NOT NULL, 
	consumption_date DATETIME NOT NULL, 
	PRIMARY KEY (consumption_id), 
	CONSTRAINT ck_consumed_quantity CHECK (consumed_quantity > 0), 
	FOREIGN KEY(order_id) REFERENCES production_orders (order_id), 
	FOREIGN KEY(lot_id) REFERENCES material_lots (lot_id)
);
CREATE TABLE material_lots (
	lot_id VARCHAR(50) NOT NULL, 
	supplier_id VARCHAR(20) NOT NULL, 
	material_code VARCHAR(30) NOT NULL, 
	supplier_batch_number VARCHAR(50) NOT NULL, 
	received_quantity FLOAT NOT NULL, 
	available_quantity FLOAT NOT NULL, 
	unit_of_measure VARCHAR(20) NOT NULL, 
	received_date DATE NOT NULL, 
	expiry_date DATE, 
	inspection_status VARCHAR(20) NOT NULL, 
	lifecycle_status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (lot_id), 
	CONSTRAINT uq_supplier_batch UNIQUE (supplier_id, supplier_batch_number), 
	CONSTRAINT ck_lot_received_quantity CHECK (received_quantity > 0), 
	CONSTRAINT ck_lot_available_quantity CHECK (available_quantity >= 0 AND available_quantity <= received_quantity), 
	CONSTRAINT ck_lot_expiry CHECK (expiry_date IS NULL OR expiry_date >= received_date), 
	CONSTRAINT ck_lot_inspection CHECK (inspection_status IN ('PENDING', 'ACCEPTED', 'REJECTED')), 
	CONSTRAINT ck_lot_status CHECK (lifecycle_status IN ('AVAILABLE', 'PARTIALLY_USED', 'CONSUMED', 'QUARANTINED')), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (supplier_id)
);
CREATE TABLE order_machine_executions (
	execution_id INTEGER NOT NULL, 
	order_id VARCHAR(30) NOT NULL, 
	machine_id VARCHAR(20) NOT NULL, 
	step_id VARCHAR(30) NOT NULL, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME, 
	PRIMARY KEY (execution_id), 
	CONSTRAINT ck_execution_dates CHECK (end_time IS NULL OR end_time >= start_time), 
	FOREIGN KEY(order_id) REFERENCES production_orders (order_id), 
	FOREIGN KEY(machine_id) REFERENCES machines (machine_id), 
	FOREIGN KEY(step_id) REFERENCES process_steps (step_id)
);
CREATE TABLE process_steps (
	step_id VARCHAR(30) NOT NULL, 
	order_id VARCHAR(30) NOT NULL, 
	machine_id VARCHAR(20) NOT NULL, 
	step_name VARCHAR(100) NOT NULL, 
	sequence_number INTEGER NOT NULL, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME, 
	temperature FLOAT, 
	pressure FLOAT, 
	process_status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (step_id), 
	CONSTRAINT uq_order_step_sequence UNIQUE (order_id, sequence_number), 
	CONSTRAINT ck_step_sequence CHECK (sequence_number > 0), 
	CONSTRAINT ck_step_dates CHECK (end_time IS NULL OR end_time >= start_time), 
	CONSTRAINT ck_process_status CHECK (process_status IN ('PENDING', 'RUNNING', 'COMPLETED', 'FAILED')), 
	FOREIGN KEY(order_id) REFERENCES production_orders (order_id), 
	FOREIGN KEY(machine_id) REFERENCES machines (machine_id)
);
CREATE TABLE production_orders (
	order_id VARCHAR(30) NOT NULL, 
	product_id VARCHAR(20) NOT NULL, 
	bom_id VARCHAR(30) NOT NULL, 
	planned_quantity INTEGER NOT NULL, 
	actual_quantity INTEGER NOT NULL, 
	start_date DATETIME NOT NULL, 
	end_date DATETIME, 
	priority VARCHAR(20) NOT NULL, 
	lifecycle_status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (order_id), 
	CONSTRAINT ck_order_planned_quantity CHECK (planned_quantity > 0), 
	CONSTRAINT ck_order_actual_quantity CHECK (actual_quantity >= 0), 
	CONSTRAINT ck_order_priority CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH')), 
	CONSTRAINT ck_order_status CHECK (lifecycle_status IN ('PLANNED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED')), 
	CONSTRAINT ck_order_dates CHECK (end_date IS NULL OR end_date >= start_date), 
	FOREIGN KEY(product_id) REFERENCES products (product_id), 
	FOREIGN KEY(bom_id) REFERENCES boms (bom_id)
);
CREATE TABLE products (
	product_id VARCHAR(20) NOT NULL, 
	product_name VARCHAR(100) NOT NULL, 
	category VARCHAR(50) NOT NULL, 
	description VARCHAR(500), 
	unit_of_measure VARCHAR(20) NOT NULL, 
	lifecycle_status VARCHAR(20) NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (product_id), 
	CONSTRAINT ck_product_status CHECK (lifecycle_status IN ('ACTIVE', 'INACTIVE'))
);
CREATE TABLE suppliers (
	supplier_id VARCHAR(20) NOT NULL, 
	supplier_name VARCHAR(100) NOT NULL, 
	supplier_location VARCHAR(100) NOT NULL, 
	supplier_category VARCHAR(50) NOT NULL, 
	quality_rating FLOAT NOT NULL, 
	lifecycle_status VARCHAR(20) NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (supplier_id), 
	CONSTRAINT ck_supplier_quality_rating CHECK (quality_rating >= 0 AND quality_rating <= 100), 
	CONSTRAINT ck_supplier_status CHECK (lifecycle_status IN ('ACTIVE', 'INACTIVE'))
);
COMMIT;
