INSERT INTO "corrective_actions" VALUES('CAPA-2026-000001','DEF-2026-000001','Incoming material did not consistently meet specification.','Notify production and quality teams and isolate suspected components.','Replace nonconforming components and reinspect finished products.','Add supplier quality monitoring and incoming material sampling.','Quality Assurance Engineer','2026-06-25 04:33:00.000000','2026-07-16','2026-07-04 04:33:00.000000',NULL,'FAILED','VERIFICATION');
INSERT INTO "corrective_actions" VALUES('CAPA-2026-000002','DEF-2026-000002','Preventive maintenance was not performed at the required interval.','Quarantine affected material lots and inspect all related inventory.','Replace nonconforming components and reinspect finished products.','Update the inspection checklist and increase inspection frequency.','Process Improvement Lead','2026-06-24 17:47:00.000000','2026-07-08',NULL,NULL,'PENDING','INVESTIGATION');
INSERT INTO "corrective_actions" VALUES('CAPA-2026-000003','DEF-2026-000003','Insufficient process control caused variation during manufacturing.','Quarantine affected material lots and inspect all related inventory.','Rework affected units and correct the manufacturing process parameters.','Train operators on the updated manufacturing work instructions.','Manufacturing Engineer','2025-11-24 12:33:00.000000','2025-12-24','2025-11-26 12:33:00.000000','2025-11-28 03:33:00.000000','PASSED','CLOSED');
